config.message:
:warning: Low-confidence AI answer for: "{{input.message}}"
Draft answer: {{input.answer}}
Please review and reply directly.

config.code:
let parsed = {};
try {
  const text = input.response || input.text || input.content || "{}";
  const m = text.match(/\{[\s\S]*\}/);
  parsed = m ? JSON.parse(m[0]) : {};
} catch (e) { parsed = {}; }
return {
  ...input,
  answer: parsed.answer || input.response || input.text || "",
  confidence: typeof parsed.confidence === "number" ? parsed.confidence : 0
};
